from .repository import contact_exists, put_contact

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

_CONTACT_FIELDS = frozenset({"email", "name"})

def _validate_row(row, index):
    if not isinstance(row, dict):
        raise ValueError(f"row {index} is not an object")
    keys = set(row.keys())
    missing = _CONTACT_FIELDS - keys
    if missing:
        raise ValueError(f"row {index} is missing fields: {sorted(missing)}")
    unknown = keys - _CONTACT_FIELDS
    if unknown:
        raise ValueError(f"row {index} has unknown fields: {sorted(unknown)}")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError(f"row {index} fields must be strings")
    email = email.strip()
    name = name.strip()
    if email.count("@") != 1:
        raise ValueError(f"row {index} email must contain exactly one '@'")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError(f"row {index} email must have nonempty local and domain parts")
    if any(ch.isspace() for ch in email):
        raise ValueError(f"row {index} email must not contain whitespace")
    if not name:
        raise ValueError(f"row {index} name must not be empty")
    return email.lower(), name

def import_contacts(connection, rows):
    if not isinstance(rows, list):
        raise ValueError("rows must be a list")
    # Validate the whole batch before touching the database.
    normalized = []
    seen = set()
    for index, row in enumerate(rows):
        email, name = _validate_row(row, index)
        if email in seen:
            raise ValueError(f"duplicate email in batch: {email}")
        seen.add(email)
        normalized.append((email, name))
    inserted = 0
    updated = 0
    # Single transaction: commits on success, rolls back on any failure.
    with connection:
        for email, name in normalized:
            existed = contact_exists(connection, email)
            put_contact(connection, email, name)
            if existed:
                updated += 1
            else:
                inserted += 1
    return {"inserted": inserted, "updated": updated}
