import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, list_contacts
from src.service import import_contacts, add_contact
from src.api import handle_import

def fresh():
    c = sqlite3.connect(":memory:")
    initialize(c)
    return c

def expect_value_error(fn):
    try:
        fn()
    except ValueError:
        return
    raise AssertionError("expected ValueError")

c = fresh()
assert import_contacts(c, []) == {"inserted": 0, "updated": 0}
assert import_contacts(c, [{"email": "  A@B.com ", "name": " Alice "}]) == {"inserted": 1, "updated": 0}
assert list_contacts(c) == [("a@b.com", "Alice")]
assert import_contacts(c, [{"email": "a@b.com", "name": "Alice"}]) == {"inserted": 0, "updated": 1}
assert import_contacts(c, [{"email": "x@y", "name": "X"}, {"email": "a@b.com", "name": "Al"}]) == {"inserted": 1, "updated": 1}
assert list_contacts(c) == [("a@b.com", "Al"), ("x@y", "X")]

# Invalid batches leave data unchanged.
before = list_contacts(c)
bad_batches = [
    [{"email": "new@x", "name": "N"}, "not-object"],
    [{"email": "new@x", "name": "N"}, {"email": "a@b.com"}],
    [{"email": "new@x", "name": "N", "extra": 1}],
    [{"email": "new@x", "name": "N"}, {"email": "A@x", "name": "B"}, {"email": "a@X", "name": "C"}],
    [{"email": "new@x", "name": "N"}, {"email": "a@b.com", "name": "   "}],
    [{"email": "bad@@x", "name": "N"}],
    [{"email": "@x", "name": "N"}],
    [{"email": "a@", "name": "N"}],
    [{"email": "a b@x", "name": "N"}],
    [{"email": "ok@x", "name": 5}],
    [{"email": "ok@x", "name": "N"}, {"email": "ok@x", "name": "M"}],
]
for batch in bad_batches:
    expect_value_error(lambda b=batch: import_contacts(c, b))
    assert list_contacts(c) == before, batch

# Envelope handling through the API.
assert handle_import(c, {"contacts": []}) == {"inserted": 0, "updated": 0}
assert handle_import(c, {"contacts": [{"email": "z@z", "name": "Z"}]}) == {"inserted": 1, "updated": 0}
for payload in [None, [], {}, {"contacts": None}, {"contacts": [], "x": 1}, {"rows": []}]:
    expect_value_error(lambda p=payload: handle_import(c, p))

# Database failure rolls back the whole batch.
class FailingConn:
    def __init__(self, inner, fail_after):
        self.inner, self.n, self.fail_after = inner, 0, fail_after
    def execute(self, sql, params=()):
        if sql.startswith("INSERT"):
            self.n += 1
            if self.n > self.fail_after:
                raise sqlite3.OperationalError("boom")
        return self.inner.execute(sql, params)
    def __enter__(self):
        return self.inner.__enter__()
    def __exit__(self, *a):
        return self.inner.__exit__(*a)

before = list_contacts(c)
try:
    import_contacts(FailingConn(c, 1), [{"email": "p@q", "name": "P"}, {"email": "r@s", "name": "R"}])
    raise AssertionError("expected failure")
except sqlite3.OperationalError:
    pass
assert list_contacts(c) == before

# add_contact still works.
add_contact(c, "a@b.com", "Alice2")
assert ("a@b.com", "Alice2") in list_contacts(c)
print("ok")
